NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'II Timothy'

CHAPTERS = {
    1: {
        1: 'Pavel, po Božji volji apostol Jezusa Kristusa, glede na obljubo življenja, ki je v Kristusu Jezusu,',
        2: 'Timóteju, mojemu srčno ljubljenemu sinu: ›Milost, usmiljenje in mir od Boga Očeta in Kristusa Jezusa, našega Gospoda.‹',
        3: 'Zahvaljujem se Bogu, ki mu služim s čisto vestjo od svojih pradedov, da se te brez prenehanja, noč in dan, spominjam v svojih molitvah',
        4: 'in silno si želim, da te vidim, zavedajoč se tvojih solz, da bom lahko izpolnjen z radostjo;',
        5: 'ko se spominjam nehlinjene vere, ki je v tebi, ki je najprej prebivala v tvoji stari materi Loídi in tvoji materi Evníki; in prepričan sem, da tudi v tebi.',
        6: 'Zatorej te spominjam, da razvnameš Božji dar, ki je v tebi po polaganju mojih rok.',
        7: 'Kajti Bog nam ni dal duha strahu, temveč moči, ljubezni in zdravega razuma.',
        8: 'Ti se torej ne sramuj pričevanja o našem Gospodu niti o meni, njegovem jetniku, temveč bodi soudeleženec trpljenj evangelija glede na Božjo moč;',
        9: '§ ki nas je rešil in nas poklical s sveto poklicanostjo, ne glede na naša dela, temveč glede na svoj lastni namen in milost, ki nam je bila dana v Kristusu Jezusu pred začetkom sveta,',
        10: 'toda sedaj je prikazana s pojavitvijo našega Odrešenika Jezusa Kristusa, ki je odpravil smrt in po evangeliju prinesel življenje in nesmrtnost na svetlobo.',
        11: 'Kateremu sem bil jaz določen za pridigarja in apostola in učitelja poganov.',
        12: 'Zaradi tega razloga tudi trpim te stvari. Pa vendar nisem osramočen, ker vem, komu sem veroval in prepričan sem, da je on zmožen obdržati to, kar sem mu izročil, za tisti dan.',
        13: 'Trdno drži vzorec zdravih besed, ki si jih slišal od mene, v veri in ljubezni, ki je v Kristusu Jezusu.',
        14: '§ To dobro stvar, ki ti je bila zaupana, varuj s Svetim Duhom, ki prebiva v nas.',
        15: 'To veš, da so se vsi, ki so v Aziji, obrnili proč od mene; izmed katerih sta Figel in Hermógen.',
        16: 'Gospod naj da usmiljenje Onezíforjevi hiši, kajti pogosto me je poživil in ni bil osramočen zaradi mojih verig.',
        17: 'Toda ko je bil v Rimu, me je zelo marljivo iskal in me našel.',
        18: 'Gospod naj mu zagotovi, da bo na tisti dan lahko našel usmiljenje od Gospoda. In ti zelo dobro veš, v kako mnogih stvareh mi je služil v Efezu.',
    },
    2: {
        1: 'Ti torej, moj sin, bodi močan v milosti, ki je v Kristusu Jezusu.',
        2: 'Stvari pa, ki si jih med mnogimi pričami slišal od mene, iste izroči zvestim ljudem, ki bodo zmožni tudi druge poučiti.',
        3: 'Ti torej prenašaj trdoto kot dober vojak Jezusa Kristusa.',
        4: 'Noben človek, ki se bojuje, se ne zapleta z zadevami tega življenja, da lahko ugodi njemu, ki ga je izbral, da bi bil vojak.',
        5: 'In če si človek prav tako prizadeva za zmago, kljub temu ni okronan, razen če si ne prizadeva zakonito.',
        6: 'Poljedelec, ki dela, mora biti prvi udeleženec sadov.',
        7: 'Preudari, kar pravim in Gospod naj ti da razumevanje v vseh stvareh.',
        8: 'Spominjaj se, da je bil Jezus Kristus, iz Davidovega semena, obujen od mrtvih glede na moj evangelij,',
        9: 'za katerega prenašam stisko kakor hudodelec, celó do vezi; toda Gospodova beseda ni zvezana.',
        10: 'Zato zaradi izvoljenih prenašam vse stvari, da bi lahko tudi oni dosegli rešitev duš, ki je v Kristusu Jezusu z večno slavo.',
        11: 'To je zvest izrek: ›Kajti če smo z njim umrli, bomo z njim tudi živeli.',
        12: 'Če trpimo, bomo z njim tudi kraljevali. Če ga zatajimo, nas bo tudi on zatajil.',
        13: 'Če ne verujemo, vendar on ostaja zvest; sebe ne more zatajiti.‹',
        14: 'Spominjaj jih o teh stvareh in naročaj jim pred Gospodom, da se ne pričkajo glede besed, kar ne koristi, temveč spodkopava poslušalce.',
        15: '§ Prizadevaj si, da se pokažeš potrjenega Bogu, delavca, ki se mu ni treba sramovati, ki pravilno razdeljuje besedo resnice.',
        16: 'Toda izogibaj se oskrunjenih in praznih blebetanj, ker se bodo okrepila k večji brezbožnosti.',
        17: 'In njihova beseda bo razjedala kakor rak; izmed katerih sta Himénaj in Filét,',
        18: 'ki sta zašla glede resnice, rekoč, da je vstajenje že minilo; in zrušila vero nekaterih.',
        19: '§ Kljub temu Božji temelj trdno stoji in ima ta pečat: »Gospod pozna te, ki so njegovi.« In: »Naj se vsak, kdor imenuje Kristusovo ime, odreče krivičnosti.«',
        20: 'Toda v veliki hiši niso samo posode iz zlata in iz srebra, temveč tudi iz lesa in iz ila; in nekatere v čast, nekatere pa v nečast.',
        21: 'Če se človek torej očisti od le-teh, bo postal posoda v čast, posvečena ter primerna za gospodarjevo uporabo in pripravljena za vsako dobro delo.',
        22: 'Béži tudi pred mladostnimi poželenji, toda sledi pravičnosti, veri, ljubezni, miru, s tistimi, ki iz čistega srca kličejo h Gospodu.',
        23: 'Toda izogibaj se nespametnih in primitivnih razprav, ker veš, da povzročajo prepire.',
        24: 'In Gospodov služabnik se ne sme prepirati, temveč [mora] biti blag do vseh ljudi, zmožen za poučevanje, potrpežljiv,',
        25: '§ da v krotkosti vzgaja te, ki nasprotujejo sebi; če jim bo Bog morda dal kesanje za priznanje resnice;',
        26: 'in da bodo lahko prišli k sebi, ven iz zanke hudiča, ki jih je ujel v svojo voljo.',
    },
    3: {
        1: 'Vedi tudi to, da bodo v poslednjih dneh nastopili nevarni časi.',
        2: 'Kajti ljudje bodo samoljubni, lakomni, bahači, ponosni, bogokletniki, neposlušni staršem, nehvaležni, nesveti,',
        3: 'brez naravne prijaznosti, prelamljali bodo premirje, lažni obtoževalci, neobrzdani, kruti, prezirljivci tistih, ki so dobri,',
        4: 'izdajalci, prekanjeni, vzvišeni, raje bi imeli užitke kakor imeli radi Boga;',
        5: 'ki imajo podobo pobožnosti, toda zanikajo njeno moč. Od takšnih se odvrni proč.',
        6: 'Kajti od te vrste so tisti, ki se plazijo v hiše in peljejo v ujetništvo neumne ženske, natovorjene z grehi, speljane s številnimi poželenji,',
        7: 'ki se vedno učè in nikoli niso zmožni priti do spoznanja resnice.',
        8: 'Torej kakor sta se Janes in Jambrés uprla Mojzesu, tako se tudi ti upirajo resnici; ljudje pokvarjenih umov, izprijeni glede vere.',
        9: 'Vendar ne bodo nič dlje napredovali, kajti njihova neumnost bo očitna vsem ljudem, kakor je bila tudi njuna.',
        10: 'Toda ti si popolnoma spoznal moj nauk, način življenja, namen, vero, potrpežljivost, ljubezen, potrpljenje,',
        11: 'preganjanja, stiske, ki so prišle k meni v Antiohiji, v Ikóniju, v Listri; kakšna preganjanja sem prestal, toda iz vseh teh me je osvobodil Gospod.',
        12: 'Da, in vsi, ki hočejo bogaboječe živeti v Kristusu Jezusu, bodo trpeli preganjanje.',
        13: 'Toda hudobneži in zapeljivci bodo postajali slabši in slabši, varali bodo in bodo varani.',
        14: 'Toda ti nadaljuj pri stvareh, ki si se jih naučil in se o njih prepričal, ker veš, od koga si se jih učil;',
        15: 'in da si od otroštva poznal sveta pisma, ki so te zmožna storiti modrega za rešitev duše po veri, ki je v Kristusa Jezusa.',
        16: 'Vse pismo je dano po navdihu od Boga in je koristno za nauk, za opomin, za grajanje, za poučevanje v pravičnosti,',
        17: 'da bi bil Božji mož lahko popoln, temeljito opremljen za vsa dobra dela.',
    },
    4: {
        1: 'Zato te rotim pred Bogom in Gospodom Jezusom Kristusom, ki bo sodil žive in mrtve ob njegovi pojavitvi in njegovem kraljestvu:',
        2: 'oznanjuj besedo, bodi takojšen v sezoni, izven sezone, grajaj, oštevaj, spodbujaj z vso potrpežljivostjo in naukom.',
        3: 'Kajti prišel bo čas, ko ne bodo hoteli prenašati zdravega nauka, ampak si bodo po svojih lastnih poželenjih, ker imajo željna ušesa, kopičili učitelje',
        4: 'in svoja ušesa bodo odvračali od resnice in zapeljani bodo v bajke.',
        5: 'Toda ti pazi v vseh stvareh, pretrpi stiske, opravi delo evangelista, naredi popoln dokaz svoje službe.',
        6: 'Kajti sedaj sem pripravljen, da bom žrtvovan in čas mojega odhoda je blizu.',
        7: 'Bojeval sem dober boj, zaključil svoj tek, vero ohranil.',
        8: 'Odslej je zame prihranjena krona pravičnosti, ki mi jo bo na tisti dan dal Gospod, pravičen sodnik; in ne samo meni, temveč tudi vsem tem, ki ljubijo njegovo pojavitev.',
        9: 'Uporabi svojo prizadevnost, da v kratkem prideš k meni,',
        10: 'kajti Demá me je zapustil, ker je vzljubil ta sedanji svet in je odpotoval v Tesaloníko; Kreskens v Galatijo, Tit v Dalmacijo.',
        11: 'Samo Luka je z menoj. Vzemi Marka in ga privedi s seboj, kajti koristen mi je za službo.',
        12: 'Tihika pa sem poslal v Efez.',
        13: 'Ko prideš, prinesi s seboj ogrinjalo, ki sem ga pustil v Troádi, pri Karpu in knjige in še posebej pergamente.',
        14: 'Kotlar Aleksander mi je storil mnogo hudega. Gospod ga nagradi glede na njegova dela.',
        15: 'Njega se tudi ti pazi, kajti silno se je upiral našim besedam.',
        16: 'Ob mojem prvem zagovoru noben človek ni stal z menoj, temveč so me vsi ljudje zapustili. Prosim Boga, da to ne bo prišlo v poštev k njihovi obtožnici.',
        17: 'Vendar je z menoj stal Gospod in me krepil, da bi lahko po meni postalo oznanjevanje popolnoma znano in da bi vsi pogani lahko slišali; in rešen sem bil iz levjih ust.',
        18: 'In Gospod me bo osvobodil iz vsakega zlega dela in me ohranil za svoje nebeško kraljestvo. Njemu bodi slava na veke vekov. Amen.',
        19: 'Pozdravi Prisko in Ákvila ter Onezíforjevo družino.',
        20: 'Erást je ostal v Korintu, le Trofima sem bolnega pustil v Miletu.',
        21: 'Uporabi svojo prizadevnost, da prideš pred zimo. Pozdravljajo te Evbúl in Pudent in Lin in Klavdija ter vsi bratje.',
        22: '§ Gospod Jezus Kristus bodi s tvojim duhom. Milost bodi z vami. Amen. [Druga poslanica Timóteju, prvemu določenemu duhovnemu nadzorniku cerkve Efežanov, je bila napisana iz Rima, ko je bil Pavel drugič priveden pred Nerona.]',
    },
}
